package com.example.demo.controller;import com.example.demo.entity.Report;import com.example.demo.repository.ReportRepository;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.web.bind.annotation.*;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.http.ResponseEntity;import org.springframework.http.HttpStatus;import java.util.Optional;import java.util.List;@RestController@RequestMapping("/api/reports")public class ReportController {    @Autowired    private ReportRepository reportRepository;    private static final Logger logger = LoggerFactory.getLogger(ReportController.class);    @GetMapping("/{reportId}")    public ResponseEntity<Report> getReportById(@PathVariable String reportId) {        logger.info("Fetching report with ID: {}", reportId);        Optional<Report> report = reportRepository.findById(reportId);        if (report.isPresent()) {            logger.info("Report found: {}", report.get());            return ResponseEntity.ok(report.get());        } else {            logger.warn("Report not found with ID: {}", reportId);            return ResponseEntity.status(HttpStatus.NOT_FOUND).body(null);        }    }    @GetMapping("/list")    public ResponseEntity<List<Report>> getAllReports() {        logger.info("Fetching all reports");        List<Report> reports = reportRepository.findAll();        return ResponseEntity.ok(reports);    }    @PostMapping("/create")    public ResponseEntity<Report> createReport(@RequestBody Report report) {        logger.info("Creating a new report");        Report savedReport = reportRepository.save(report);        logger.info("Report created with ID: {}", savedReport.getId());        return ResponseEntity.status(HttpStatus.CREATED).body(savedReport);    }    @PutMapping("/update/{reportId}")    public ResponseEntity<Report> updateReport(@PathVariable String reportId, @RequestBody Report reportDetails) {        logger.info("Updating report with ID: {}", reportId);        Optional<Report> reportOptional = reportRepository.findById(reportId);        logger.info("Received Report Details: {}", reportDetails);        if (reportOptional.isPresent()) {            Report existingReport = reportOptional.get();            existingReport.setDescription(reportDetails.getDescription());            existingReport.setTitle(reportDetails.getTitle());            existingReport.setDate(reportDetails.getDate());            existingReport.setCompanyName(reportDetails.getCompanyName());            existingReport.setInviterName(reportDetails.getInviterName());            existingReport.setTechStackName(reportDetails.getTechStackName());            existingReport.setBdName(reportDetails.getBdName());            existingReport.setProfileName(reportDetails.getProfileName());            existingReport.setUspName(reportDetails.getUspName());            existingReport.setStatus(reportDetails.getStatus());            Report updatedReport = reportRepository.save(existingReport);            logger.info("Report updated: {}", updatedReport);            return ResponseEntity.ok(updatedReport);        } else {            logger.warn("Can't update Report with ID: {}", reportId);            return ResponseEntity.status(HttpStatus.NOT_FOUND).body(null);        }    }}